create policy "Hebrew bucket anon boundary" on storage.objects as restrictive for all to anon using (bucket_id <> 'hebrew-sounds') with check (bucket_id <> 'hebrew-sounds');
create policy "Hebrew bucket recorder boundary" on storage.objects as restrictive for all to authenticated using (bucket_id <> 'hebrew-sounds' or exists (select 1 from public.hebrew_recorders where user_id = (select auth.uid()))) with check (bucket_id <> 'hebrew-sounds' or (name ~ '^[a-z-]+/[0-9a-f-]+\.(webm|ogg|mp4|wav|mp3)$' and exists (select 1 from public.hebrew_recorders where user_id = (select auth.uid()))));
